-- =====================================================================
-- 873 - AKILCI TEST İSTEMİ (Bakanlık EK-2 iş kuralı kılavuzu)
--
-- Kaynak: Sağlık Bakanlığı "Akılcı Test İstemi Uygulamaları Kapsamında
--   Sağlık Bilgi Sistemlerine Entegre Edilecek İş Kuralı Kılavuzu" (EK2 pdf)
--   + "Akılcı Test İstem Listesi" (xlsx, 2.224 satır) + SKRS listeleri
--   (AKILCI TEST İSTEM LİSTESİ 2.162 · GEREKÇESİ 5 · KLİNİK GEREKÇESİ 4 ·
--   TEST ÖLÇÜM BİRİMİ 95 · KLİNİKLER). Kullanıcı: "akılcı test istem
--   kurallarını projeye ekle".
--
-- BEŞ KURAL, üç tablo:
--   1) BRANŞ KISITI  - lab_akilci_kural.brans_kodlari: SKRS klinik kodları (virgüllü)
--      (departman.kod aynı kod sistemi). Boş + tum_branslar=1 = herkes.
--      Hekimin branşı taraf.departman -> departman.kod. Kısıt dışı hekim
--      istem yapamaz; KLİNİK GEREKÇE (SKRS listesi) ile aşılabilir, kayıt
--      lab_akilci_gerekce'ye düşer (kılavuz §3).
--   2) SÜRE KISITI   - sure_gun (SKRS ISTEMSURESI; 0 = yok). Aynı hastada
--      sonuçlanmış istem varsa ve gün dolmadıysa uyarı + son 2 sonuç;
--      hekim GEREKÇE (SKRS listesi) seçerse izin, "Hayır" derse iptal
--      kaydı (§4). Xlsx'in serbest süre metni sure_notu'da kalır; bayraklar
--      (pozitifse_istenemez, tek_sefer, gebelikte_tek, yatan_serbest,
--      yalniz_yatan) uyarı metnine girer, motor yalnız gün sayar.
--   3) BASAMAK KISITI - basamak: 2 = 2. ve 3. basamak, 3 = yalnız 3.,
--      0 = kapsam dışı. Kurumun basamağı kurum_profil.basamak (null =
--      denetlenmez). Uymuyorsa istem ENGEL (§5, sevk mesajı).
--   4) REFLEKS TEST  - lab_refleks_kural: sonuç eşiği aşınca ikincil
--      tetkik otomatik eklenir (§6). Kural kurumun laboratuvarınındır;
--      burada tablo + fonksiyon, seed yok.
--   5) REFLEKTİF     - lab uzmanının sonuç sonrası istemi: lab_istem
--      satırında kaynak = 'reflektif' (§7). Uygulama katmanında.
--
-- Veri: SKRS süre kazanır; branş/basamak/not xlsx'ten (SKRS'de yok).
--   Xlsx branş yazımı bozuk (HEMOTOLOJI, ROMOTOLOJI...) - 165 jeton elle
--   takma adla SKRS klinik koduna çevrildi; çözülemeyen jetonlar
--   brans_ham'da durur ("denetimli serbestlik" klinik değil). SKRS'de olup
--   xlsx'te olmayan kodlar herkese açık (yalnız süre).
-- Tekrar çalıştırılabilir (sut_kodu üstünden upsert).
-- =====================================================================

-- ------------------------------------------------ SKRS kod listeleri
on conflict (kod) do update set ad = excluded.ad, skrs_liste = excluded.skrs_liste;

with v(deger, ad) as (values
      (1, 'KLİNİK UYUMSUZLUK'::varchar),
      (2, 'TEDAVİNİN TAKİBİ'::varchar),
      (3, 'REPLASMAN TEDAVİSİNİN TAKİBİ'::varchar),
      (5, 'YENİ HASTALIK GELİŞİMİ'::varchar)
)
select l.id, v.deger, 0, v.ad, least(v.deger, 32000)::smallint, 1, v.deger::varchar, v.ad
  from v cross join public.kod_liste l
 where l.kod = 'lab.akilci_gerekce'
on conflict (liste_id, deger, dil) do update
   set ad = excluded.ad, aktif = 1, skrs_kod = excluded.skrs_kod, skrs_ad = excluded.skrs_ad;

on conflict (kod) do update set ad = excluded.ad, skrs_liste = excluded.skrs_liste;

