-- ------------------------------------------------------ kural tablosu
create table if not exists public.lab_akilci_kural (
    id            integer generated by default as identity primary key,
    sut_kodu      varchar(20)  not null,
    ad            varchar(200) not null default '',
    hizmet_id     integer,
    sure_gun      integer      not null default 0,
    sure_notu     varchar(300) not null default '',
    bayraklar     varchar(120) not null default '',
    brans_kodlari varchar(400) not null default '',   -- SKRS klinik kodları, virgülle (departman.kod)
    tum_branslar  smallint     not null default 0,
    refleks       smallint     not null default 0,
    kapali        smallint     not null default 0,
    basamak       smallint     not null default 0,
    aciklama      varchar(600) not null default '',
    brans_ham     varchar(600) not null default '',
    aktif         smallint     not null default 1,
    kaynak_surum  varchar(40)  not null default 'EK2-2025 / SKRS 2026-09',
    ekleme_tarihi timestamp    not null default now(),
    degistirme_tarihi timestamp
);
create unique index if not exists ux_lab_akilci_kural_sut on public.lab_akilci_kural (sut_kodu);
create index if not exists ix_lab_akilci_kural_hizmet on public.lab_akilci_kural (hizmet_id);
comment on table public.lab_akilci_kural is
    'Akılcı test istemi kuralı (873): SUT kodu başına branş kısıtı (SKRS klinik kodları), tekrar süresi (gün), basamak kısıtı, refleks/kapalı bayrakları.';

-- Hekimin gerekçeli istemi / vazgeçmesi (kılavuz §4.5-4.6, §3): Bakanlık analizine gider.
create table if not exists public.lab_akilci_gerekce (
    id            bigint generated by default as identity primary key,
    istem_id      integer,
    satir_id      integer,
    hizmet_id     integer      not null,
    hasta_id      integer      not null,
    hekim_id      integer      not null,
    kural_turu    varchar(10)  not null,   -- sure | brans | basamak
    karar         varchar(10)  not null,   -- devam | iptal
    gerekce_kod   smallint,                -- lab.akilci_gerekce (süre) / lab.akilci_klinik_gerekce (branş)
    aciklama      varchar(300) not null default '',
    son_sonuc_tarihi timestamp,
    sube_id       integer,
    ekleyen       integer      not null default 0,
    ekleme_tarihi timestamp    not null default now()
);
create index if not exists ix_lab_akilci_gerekce_hasta on public.lab_akilci_gerekce (hasta_id, hizmet_id, ekleme_tarihi desc);
comment on table public.lab_akilci_gerekce is
    'Akılcı test istemi kararı (873): süre/branş/basamak uyarısında hekimin gerekçesi (devam) ya da vazgeçmesi (iptal).';

-- Refleks test kuralı (§6): tetkik sonucu eşiği aşınca ikincil tetkik eklenir.
create table if not exists public.lab_refleks_kural (
    id            integer generated by default as identity primary key,
    tetkik_id     integer      not null,
    kosul         varchar(10)  not null default '>',   -- > | < | >= | <= | pozitif | anormal
    esik          numeric(18,6),
    hedef_tetkik_id integer    not null,
    aciklama      varchar(300) not null default '',
    aktif         smallint     not null default 1,
    sube_id       integer,
    ekleyen       integer      not null default 0,
    ekleme_tarihi timestamp    not null default now()
);
create index if not exists ix_lab_refleks_kural_tetkik on public.lab_refleks_kural (tetkik_id) where aktif = 1;
comment on table public.lab_refleks_kural is
    'Refleks test kuralı (873): kaynak tetkik sonucu koşulu sağlayınca hedef tetkik aynı isteme otomatik eklenir. Kurum laboratuvarı tanımlar.';

-- ------------------------------------------------------------ veri
drop table if exists t873;
create temp table t873 (sut varchar(20) primary key, ad varchar(200), gun integer, sure_notu varchar(300), bayraklar varchar(120),
                        brans_kodlari varchar(400), tum smallint, refleks smallint, kapali smallint, basamak smallint,
                        aciklama varchar(600), brans_ham varchar(600));

select t.sut, t.ad, h.id, t.gun, t.sure_notu, t.bayraklar, t.brans_kodlari, t.tum, t.refleks, t.kapali, t.basamak, t.aciklama, t.brans_ham
  from t873 t left join public.hizmet h on h.kod = t.sut
on conflict (sut_kodu) do update set
  ad = excluded.ad, hizmet_id = coalesce(excluded.hizmet_id, public.lab_akilci_kural.hizmet_id),
  sure_gun = excluded.sure_gun, sure_notu = excluded.sure_notu, bayraklar = excluded.bayraklar,
  brans_kodlari = excluded.brans_kodlari, tum_branslar = excluded.tum_branslar, refleks = excluded.refleks,
  kapali = excluded.kapali, basamak = excluded.basamak, aciklama = excluded.aciklama,
  brans_ham = excluded.brans_ham, degistirme_tarihi = now();


-- ------------------------------------------------------- istem satırı kaynağı
-- 0 hekim/banko · 1 refleks (sistem, §6) · 2 reflektif (lab uzmanı, §7)
alter table public.lab_istem_satir add column if not exists kaynak_turu smallint not null default 0;

-- ------------------------------------------------------------ fonksiyon
-- TESİS BASAMAĞI ŞUBEDE (kullanıcı: "şubeye basamak mı eklesek"): her şube ayrı
--   tesistir; sube.basamak 1 / 2 / 3, VARSAYILAN 2 (kullanıcı: "default basamak
--   2 olsun"). kurum_profil.basamak metninde rakam varsa ("3. basamak") o
--   yazılır. 0 = denetlenmez (bilinçli kapatma).
alter table public.sube add column if not exists basamak smallint not null default 2;
comment on column public.sube.basamak is 'Sağlık tesisi basamağı (873): 1 / 2 / 3, varsayılan 2; 0 = akılcı istem basamak kısıtı denetlenmez.';
update public.sube s set basamak = k.b
  from (select kp.sube_id, nullif(substring(kp.basamak from '^\s*([123])'), '')::smallint as b
          from public.kurum_profil kp) k
 where k.sube_id = s.id and k.b is not null and s.basamak <> k.b;

create or replace function public.fn_kurum_basamak(p_sube integer)
returns smallint
language sql stable
as $$
    select coalesce((select s.basamak from public.sube s where s.id = p_sube), 2)::smallint;
$$;

/**
 * AKILCI TEST İSTEMİ DENETİMİ (873). Tetkik listesi için kural sonuçları:
 *   seviye  'engel' (istem açılamaz: kapalı / basamak) · 'uyari' (hekim
 *           gerekçeyle geçebilir: süre / branş)
 *   kural   'kapali' | 'basamak' | 'brans' | 'sure'
 * Süre: aynı hastanın aynı tetkikte ONAYLI son sonucu (lab_sonuc.durum=3) ya da
 *   henüz sonuçlanmamış açık istemi sure_gun içindeyse uyarı; son 2 sonuç
 *   jsonb olarak döner (kılavuz §4.2 "son iki başvuru").
 * Branş: hekimin bölümü (taraf.departman -> departman.kod = SKRS klinik kodu)
 *   kuralın branş listesinde değilse uyarı. Hekim yoksa (banko) denetlenmez.
 * Kural yoksa satır dönmez.
 */
create or replace function public.fn_lab_akilci_kontrol(
    p_hasta integer, p_hekim integer, p_sube integer, p_tetkikler integer[])
returns table (
    tetkik_id integer, hizmet_id integer, sut_kodu varchar, ad varchar,
    kural varchar, seviye varchar, mesaj text,
    sure_gun integer, son_tarih timestamp, kalan_gun integer,
    sonuclar jsonb, hekim_brans varchar, brans_kodlari varchar, bayraklar varchar, sure_notu varchar)
language plpgsql stable
as $$
declare
    v_basamak smallint := public.fn_kurum_basamak(p_sube);
    v_brans   varchar  := (select d.kod from public.taraf t join public.departman d on d.id = t.departman
                            where t.id = p_hekim);
    v_brans_ad varchar := (select d.ad from public.taraf t join public.departman d on d.id = t.departman
                            where t.id = p_hekim);
    r record; v_son timestamp; v_kalan integer; v_sonuclar jsonb;
begin
    for r in
        select t.id as tid, h.id as hid, k.*
          from unnest(p_tetkikler) x(id)
          join public.lab_tetkik t on t.id = x.id
          join public.hizmet h on h.id = t.hizmet_id
          join public.lab_akilci_kural k on (k.hizmet_id = h.id or k.sut_kodu = h.kod) and k.aktif = 1
    loop
        tetkik_id := r.tid; hizmet_id := r.hid; sut_kodu := r.sut_kodu; ad := r.ad;
        sure_gun := r.sure_gun; bayraklar := r.bayraklar; sure_notu := r.sure_notu;
        brans_kodlari := r.brans_kodlari; hekim_brans := v_brans_ad; son_tarih := null; kalan_gun := null; sonuclar := null;

        if r.kapali = 1 then
            kural := 'kapali'; seviye := 'engel';
            mesaj := r.ad || ': bu test Akılcı Test İstem listesinde isteme kapalı (kapsam dışı).'
                     || case when r.aciklama <> '' then ' ' || r.aciklama else '' end;
            return next; continue;
        end if;

        if r.basamak = 3 and v_basamak = 2 then
            kural := 'basamak'; seviye := 'engel';
            mesaj := 'Talep edilen test (' || r.ad || ') sağlık tesisinizde çalışılmamaktadır (yalnız 3. basamak). '
                     || 'Bu test için hastanın uygun bir üçüncü basamak sağlık tesisine sevki önerilmektedir.';
            return next; continue;
        end if;

        if p_hekim is not null and p_hekim > 0 and r.tum_branslar = 0
           and (v_brans is null or not (v_brans = any(string_to_array(r.brans_kodlari, ',')))) then
            kural := 'brans'; seviye := 'uyari';
            mesaj := r.ad || ' testi ' || coalesce(v_brans_ad, 'branşı tanımsız hekim')
                     || ' branşına doğrudan açık değil. Yetkili branşlar: '
                     || coalesce((select string_agg(d.ad, ', ' order by d.ad)
                                    from public.departman d where d.kod = any(string_to_array(r.brans_kodlari, ','))), '(tanımsız)')
                     || case when r.refleks = 1 then '. Refleks test: laboratuvar uzmanı ister.' else '.' end
                     || ' Klinik gerekçe seçilerek istenebilir ya da yetkili branştan konsültasyon istenir.';
            return next;
        end if;

        if r.sure_gun > 0 then
            select max(z) into v_son from (
                select coalesce(ls.onay_zamani, ls.olcum_zamani)::timestamp as z
                  from public.lab_sonuc ls
                  join public.lab_istem_satir s on s.id = ls.istem_satir_id
                  join public.lab_istem i on i.id = s.istem_id
                 where i.taraf_id = p_hasta and s.tetkik_id = r.tid and ls.durum = 3
                union all
                select i.istem_tarihi::timestamp
                  from public.lab_istem i
                  join public.lab_istem_satir s on s.istem_id = i.id
                 where i.taraf_id = p_hasta and s.tetkik_id = r.tid
                   and i.durum <> 9 and s.durum <> 9
            ) q;
            if v_son is not null and v_son > now() - make_interval(days => r.sure_gun) then
                v_kalan := r.sure_gun - (now()::date - v_son::date);
                select jsonb_agg(jsonb_build_object('tarih', z.zaman, 'deger', z.deger, 'birim', z.birim,
                                                    'bayrak', z.bayrak, 'durum', z.durum))
                  into v_sonuclar
                  from (select coalesce(ls.onay_zamani, ls.olcum_zamani) as zaman,
                               coalesce(ls.deger_metin, ls.deger_sayisal::text) as deger, ls.birim, ls.bayrak,
                               case ls.durum when 3 then 'onaylı' when 4 then 'iptal' else 'bekliyor' end as durum
                          from public.lab_sonuc ls
                          join public.lab_istem_satir s on s.id = ls.istem_satir_id
                          join public.lab_istem i on i.id = s.istem_id
                         where i.taraf_id = p_hasta and s.tetkik_id = r.tid and ls.durum <> 4
                         order by coalesce(ls.onay_zamani, ls.olcum_zamani) desc limit 2) z;
                kural := 'sure'; seviye := 'uyari'; son_tarih := v_son; kalan_gun := v_kalan; sonuclar := v_sonuclar;
                mesaj := 'Bu testin (' || r.ad || ') ' || to_char(v_son, 'DD.MM.YYYY') || ' tarihinde yapılmış bir '
                         || case when v_sonuclar is null then 'istemi' else 'sonucu' end
                         || ' bulunmaktadır (tekrar aralığı ' || r.sure_gun || ' gün, ' || v_kalan || ' gün kaldı). '
                         || 'Tekrar istemek istediğinizden emin misiniz?'
                         || case when r.sure_notu <> '' then ' Not: ' || r.sure_notu else '' end;
                return next;
            end if;
        end if;
    end loop;
end $$;

comment on function public.fn_lab_akilci_kontrol(integer, integer, integer, integer[]) is
    'Akılcı test istemi denetimi (873): kapalı/basamak = engel, branş/süre = gerekçeyle aşılabilir uyarı; son 2 sonuç jsonb.';

drop table if exists t873;

-- Bağlamsal yardım ekran kataloğu (871 deseni): yeni ekranlar.
on conflict (rota) do update set baslik = excluded.baslik, yol = excluded.yol, menu_grup = excluded.menu_grup,
  menu_ad = excluded.menu_ad, yetki_kodu = excluded.yetki_kodu, anahtar = excluded.anahtar, aksiyon_ekrani = excluded.aksiyon_ekrani;

do $$
declare v_kural integer; v_hizmetsiz integer; v_branssiz integer;
begin
    select count(*), count(*) filter (where hizmet_id is null),
           count(*) filter (where tum_branslar = 0 and brans_kodlari = '' and kapali = 0 and refleks = 0)
      into v_kural, v_hizmetsiz, v_branssiz from public.lab_akilci_kural;
    raise notice '873 tamam: % akılcı kural (% hizmet kataloğunda yok, % branşı çözülemedi); kod listeleri lab.akilci_gerekce / lab.akilci_klinik_gerekce / lab.olcum_birimi',
        v_kural, v_hizmetsiz, v_branssiz;
end $$;
